    key = str(value).strip().lower()
    named = {
        'white': '#ffffff', 'black': '#000000', 'red': '#e53935', 'green': '#43a047',
        'blue': '#1e88e5', 'grey': '#9e9e9e', 'gray': '#9e9e9e', 'pink': '#e91e63',
    }
